const yesterday = $now.minus({ days: 1 });
const start = yesterday.startOf('day').toMillis();
const end = yesterday.endOf('day').toMillis();
const all = [];
for (const item of $input.all()) {
  const list = (item.json && item.json.matches) || [];
  for (const m of list) all.push(m);
}
const day = all.filter((m) => {
  if (!m.played || !m.playedAt || !m.outcome) return false;
  const t = new Date(m.playedAt).getTime();
  return t >= start && t <= end;
});
if (day.length === 0) return [];

const eloByPlayer = {};
let eloMissing = 0;
let biggestSwing = null;
for (const m of day) {
  const rc = m.ratingChange;
  if (!rc || typeof rc.p1 !== 'number' || typeof rc.p2 !== 'number') { eloMissing++; continue; }
  for (const [name, delta] of [[m.playerP1.name, rc.p1], [m.playerP2.name, rc.p2]]) {
    if (!eloByPlayer[name]) eloByPlayer[name] = { player: name, netChange: 0, matchesRated: 0, gains: 0, losses: 0 };
    eloByPlayer[name].netChange += delta;
    eloByPlayer[name].matchesRated++;
    if (delta > 0) eloByPlayer[name].gains++; else if (delta < 0) eloByPlayer[name].losses++;
  }
  const top = Math.abs(rc.p1) >= Math.abs(rc.p2) ? [m.playerP1.name, rc.p1] : [m.playerP2.name, rc.p2];
  if (!biggestSwing || Math.abs(top[1]) > Math.abs(biggestSwing.change)) biggestSwing = { player: top[0], change: Math.round(top[1] * 100) / 100, match: m.playerP1.name + ' (' + m.teamP1.name + ') ' + m.scoreP1 + ' - ' + m.scoreP2 + ' (' + m.teamP2.name + ') ' + m.playerP2.name, tournament: m.tournament ? m.tournament.name : null, stage: m.type };
}
// Tamaño del mayor movimiento de ELO de un solo partido, calculado acá para que el agente no tenga que conocer ninguna escala.
const swingSize = (change) => { const a = Math.abs(change); return a < 4 ? 'small' : a < 9 ? 'medium' : 'huge'; };
if (biggestSwing) biggestSwing.size = swingSize(biggestSwing.change);
const eloChanges = Object.values(eloByPlayer).map((e) => Object.assign(e, { netChange: Math.round(e.netChange * 100) / 100 })).sort((a, b) => b.netChange - a.netChange);
const elo = eloChanges.length ? { players: eloChanges, biggestSingleMatchSwing: biggestSwing, matchesWithoutRating: eloMissing } : null;

const groups = {};
for (const m of day) {
  const tid = m.tournament ? String(m.tournament._id || m.tournament.id || m.tournament.name) : 'unknown';
  if (!groups[tid]) groups[tid] = { tournamentId: tid, tournament: m.tournament ? m.tournament.name : 'Sin torneo', raw: [] };
  groups[tid].raw.push(m);
}

// Quién ganó según el outcome (una tanda de penales es victoria del ganador); sin outcome usable cae al marcador.
const sameId = (a, b) => a !== undefined && a !== null && b !== undefined && b !== null && String(a) === String(b);
const sideOf = (m, s1, s2) => {
  const o = m.outcome || {};
  if (o.draw === true && o.penalties !== true) return 'draw';
  const pid = o.playerThatWon && o.playerThatWon.id;
  const onP1 = sameId(pid, m.playerP1 && m.playerP1.id);
  const onP2 = sameId(pid, m.playerP2 && m.playerP2.id);
  if (onP1 !== onP2) return onP1 ? 'p1' : 'p2';
  const tid = o.teamThatWon && o.teamThatWon.id;
  const tP1 = sameId(tid, m.teamP1 && m.teamP1.id);
  const tP2 = sameId(tid, m.teamP2 && m.teamP2.id);
  if (tP1 !== tP2) return tP1 ? 'p1' : 'p2';
  return s1 > s2 ? 'p1' : s1 < s2 ? 'p2' : 'draw';
};

const build = (g) => {
  const players = {};
  const get = (name) => {
    if (!players[name]) players[name] = { player: name, played: 0, wins: 0, draws: 0, losses: 0, goalsFor: 0, goalsAgainst: 0 };
    return players[name];
  };
  const matches = g.raw
    .sort((a, b) => new Date(a.playedAt) - new Date(b.playedAt))
    .map((m) => {
      const p1 = get(m.playerP1.name);
      const p2 = get(m.playerP2.name);
      const s1 = Number(m.scoreP1 || 0);
      const s2 = Number(m.scoreP2 || 0);
      p1.played++; p2.played++;
      p1.goalsFor += s1; p1.goalsAgainst += s2;
      p2.goalsFor += s2; p2.goalsAgainst += s1;
      const side = sideOf(m, s1, s2);
      if (side === 'draw') { p1.draws++; p2.draws++; }
      else if (side === 'p1') { p1.wins++; p2.losses++; }
      else { p2.wins++; p1.losses++; }
      return {
        time: m.playedAt,
        stage: m.type,
        playoffId: m.playoff_id === undefined ? null : m.playoff_id,
        leg: m.leg === undefined ? null : m.leg,
        seeds: m.seedP1 && m.seedP2 ? m.seedP1 + ' vs ' + m.seedP2 : null,
        home: m.playerP1.name + ' (' + m.teamP1.name + ')',
        away: m.playerP2.name + ' (' + m.teamP2.name + ')',
        score: s1 + ' - ' + s2,
        totalGoals: s1 + s2,
        margin: Math.abs(s1 - s2),
      };
    });
  const totalGoals = matches.reduce((a, m) => a + m.totalGoals, 0);
  const biggestWin = matches.slice().sort((a, b) => b.margin - a.margin)[0];
  const mostGoals = matches.slice().sort((a, b) => b.totalGoals - a.totalGoals)[0];
  const table = Object.values(players).sort((a, b) => (b.wins * 3 + b.draws) - (a.wins * 3 + a.draws) || (b.goalsFor - b.goalsAgainst) - (a.goalsFor - a.goalsAgainst));
  const rank = { playoff: 0, playin: 1, regular: 2 };
  matches.sort((a, b) => (rank[a.stage] ?? 3) - (rank[b.stage] ?? 3) || new Date(a.time) - new Date(b.time));
  const byStage = { playoff: 0, playin: 0, regular: 0 };
  for (const m of matches) byStage[m.stage] = (byStage[m.stage] || 0) + 1;
  const series = {};
  for (const m of matches) {
    if (m.stage !== 'playoff' || m.playoffId === null) continue;
    series[m.playoffId] = series[m.playoffId] || { playoffId: m.playoffId, seeds: m.seeds, legsPlayedYesterday: [] };
    series[m.playoffId].legsPlayedYesterday.push({ leg: m.leg, home: m.home, away: m.away, score: m.score });
  }
  return { tournamentId: g.tournamentId, tournament: g.tournament, matchCount: matches.length, matchesByStage: byStage, playoffSeries: Object.values(series), totalGoals, avgGoals: Math.round((totalGoals / matches.length) * 100) / 100, biggestWin, mostGoals, playerTable: table, matches };
};
const tournaments = Object.values(groups).map(build);
const totalGoals = tournaments.reduce((a, t) => a + t.totalGoals, 0);
return [{ json: { date: yesterday.toFormat('yyyy-MM-dd'), matchCount: day.length, totalGoals, tournamentCount: tournaments.length, elo, tournaments } }];

const base = $('Compute Day Stats').first().json;
const stats = $input.first().json || {};
const zone = 'America/Buenos_Aires';
const d = DateTime.fromISO(base.date, { zone });
const start = d.startOf('day').toMillis();
const end = d.endOf('day').toMillis();
const inDay = (iso) => { if (!iso) return false; const t = new Date(iso).getTime(); return t >= start && t <= end; };

const label = {
  most_clean_sheets_in_a_row: 'clean sheets in a row',
  most_consecutive_matches_scoring_1_plus_goals: 'matches in a row scoring 1+ goals',
  most_consecutive_matches_scoring_2_plus_goals: 'matches in a row scoring 2+ goals',
  most_consecutive_matches_scoring_3_plus_goals: 'matches in a row scoring 3+ goals',
  most_wins_in_a_row: 'wins in a row',
  most_draws_in_a_row: 'draws in a row',
  most_losses_in_a_row: 'losses in a row',
  most_unbeaten_in_a_row: 'unbeaten matches in a row',
  most_penalty_shootout_wins_in_a_row: 'penalty shootout wins in a row',
  most_knockout_wins_in_a_row: 'knockout wins in a row',
  most_knockout_unbeaten_in_a_row: 'unbeaten knockout matches in a row',
  most_consecutive_semifinals: 'semifinals in a row',
  most_consecutive_finals: 'finals in a row',
  most_consecutive_titles: 'titles in a row',
};
const brief = (m) => m ? { date: m.date, tournament: m.tournament && m.tournament.name, stage: m.type, team: m.team && m.team.name, opponent: m.opponent && m.opponent.name, opponentTeam: m.opponentTeam && m.opponentTeam.name, score: m.goalsFor + ' - ' + m.goalsAgainst, result: m.result } : null;

const events = [];
const records = stats.records || {};
const active = stats.activeStreaks || {};
for (const [key, sec] of Object.entries(records)) {
  if (!sec || !Array.isArray(sec.players)) continue;
  for (const p of sec.players) {
    if (!p.isActive && p.breakMatch && inDay(p.breakMatch.date)) {
      events.push({ event: 'RECORD_STREAK_BROKEN', streakType: label[key] || key, player: p.name, length: sec.count, note: 'This was the all-time record streak of this type; it ended on that day. The record itself still stands.', brokenBy: brief(p.breakMatch) });
    } else if (p.isActive && inDay(p.endDate)) {
      events.push({ event: 'RECORD_STREAK_EXTENDED', streakType: label[key] || key, player: p.name, length: sec.count, note: 'This active streak is the all-time record for this type and it grew that day.', lastMatch: brief(p.endMatch) });
    }
  }
}
for (const [key, sec] of Object.entries(active)) {
  if (!sec || !Array.isArray(sec.players)) continue;
  for (const p of sec.players) {
    if (!p.isActive || !inDay(p.endDate)) continue;
    const alsoRecord = records[key] && Array.isArray(records[key].players) && records[key].players.some((r) => r.id === p.id && r.startDate === p.startDate);
    if (alsoRecord) continue;
    // Si otro jugador cortó ese día el récord de este mismo tipo, esta racha pasó a ser la activa más larga porque se cortó la de él.
    const cut = records[key] && Array.isArray(records[key].players) ? records[key].players.find((r) => String(r.id) !== String(p.id) && !r.isActive && r.breakMatch && inDay(r.breakMatch.date)) : null;
    const ev = { event: 'ACTIVE_STREAK_EXTENDED', streakType: label[key] || key, player: p.name, length: sec.count, startedThatDay: inDay(p.startDate), note: 'Longest currently active streak of this type; it grew that day.', lastMatch: brief(p.endMatch) };
    if (cut) { ev.takesOverFrom = { player: cut.name, length: records[key].count }; ev.note = 'This became the longest active streak of this type because the record streak of ' + cut.name + ' ended that day.'; }
    events.push(ev);
  }
}

const played = new Set();
for (const t of base.tournaments) for (const m of t.matches) { played.add(m.home.replace(/ \(.*$/, '')); played.add(m.away.replace(/ \(.*$/, '')); }
const form = [];
for (const p of (stats.players || [])) {
  const name = p.player && p.player.name;
  if (!name || !played.has(name)) continue;
  const recent = (p.recent || []).map((m) => {
    const isP1 = m.playerP1 && m.playerP1.name === name;
    return { date: m.date, tournament: m.tournament, opponent: isP1 ? m.playerP2.name : m.playerP1.name, score: isP1 ? m.scoreP1 + ' - ' + m.scoreP2 : m.scoreP2 + ' - ' + m.scoreP1, outcome: m.outcome };
  });
  form.push({ player: name, currentStreak: p.current_streak, last10Outcomes: recent.map((r) => String(r.outcome).toUpperCase()).join(''), last10: recent });
}
return [{ json: Object.assign({}, base, { streakEvents: events, playersForm: form }) }];

const base = $('Compute Streak Events').first().json;
const list = $input.all().map((i) => i.json || {}).flatMap((j) => Array.isArray(j.data) ? j.data : (j.tournamentId ? [j] : []));
if (!list.length) return [{ json: base }];
const teamOf = (s) => { const i = s.lastIndexOf('('); return i >= 0 ? s.slice(i + 1, s.lastIndexOf(')')) : s; };
const byId = {};
for (const c of list) byId[c.tournamentId] = c;
const tournamentContext = [];
for (const t of base.tournaments) {
  const c = byId[t.tournamentId];
  if (!c) continue;
  const teams = new Set();
  const playoffIds = new Set();
  for (const m of t.matches) {
    teams.add(teamOf(m.home));
    teams.add(teamOf(m.away));
    if (m.stage === 'playoff' && m.playoffId !== null) playoffIds.add(m.playoffId);
  }
  const standings = (c.standings || [])
    .filter((g) => (g.teams || []).some((r) => teams.has(r.team.name)))
    .map((g) => {
      const size = g.teams.length;
      const rows = g.teams.map((r) => ({ r, remaining: Math.max(0, (size - 1) - r.played) }));
      const complete = rows.every((x) => x.remaining === 0);
      const out = rows.map(({ r, remaining }) => {
        let locked = true;
        if (complete) return { position: r.position, previousPosition: r.previousPosition, team: r.team.name, player: r.player.name, played: r.played, remainingMatches: 0, maxPossiblePoints: r.points, positionLocked: true, wins: r.wins, draws: r.draws, losses: r.losses, goalsFor: r.goalsFor, goalsAgainst: r.goalsAgainst, points: r.points };
        for (const o of rows) {
          if (o.r === r) continue;
          const oMax = o.r.points + 3 * o.remaining;
          const myMax = r.points + 3 * remaining;
          if (o.r.position > r.position) { if (oMax >= r.points) locked = false; }
          else if (myMax >= o.r.points) locked = false;
        }
        return { position: r.position, previousPosition: r.previousPosition, team: r.team.name, player: r.player.name, played: r.played, remainingMatches: remaining, maxPossiblePoints: r.points + 3 * remaining, positionLocked: locked, wins: r.wins, draws: r.draws, losses: r.losses, goalsFor: r.goalsFor, goalsAgainst: r.goalsAgainst, points: r.points };
      });
      return { group: g.group, matchesPerTeamInGroup: size - 1, groupComplete: out.every((t) => t.remainingMatches === 0), teams: out };
    });
  const bracket = (c.bracket || [])
    .filter((b) => playoffIds.has(b.playoffId))
    .map((b) => {
      const names = {};
      for (const m of b.matches) { names[m.teamP1.id] = m.teamP1.name; names[m.teamP2.id] = m.teamP2.name; }
      const s = b.series;
      return {
        playoffId: b.playoffId,
        round: b.round,
        series: s ? { status: s.status, aggregate: (s.aggregate || []).map((a) => ({ team: names[a.teamId] || a.teamId, score: a.score })), winner: s.winnerTeamId ? (names[s.winnerTeamId] || s.winnerTeamId) : null } : null,
        matches: b.matches.map((m) => ({ leg: m.leg, played: m.played, seeds: m.seedP1 + ' vs ' + m.seedP2, home: m.teamP1.name + ' (' + m.playerP1.name + ')', away: m.teamP2.name + ' (' + m.playerP2.name + ')', score: m.played ? m.scoreP1 + ' - ' + m.scoreP2 : null })),
      };
    });
  tournamentContext.push({ tournamentId: c.tournamentId, tournament: c.tournament, format: c.format, ongoing: c.ongoing, asOf: c.asOf, rules: c.rules, standings, playin: c.playin, bracket });
}
return [{ json: Object.assign({}, base, { tournamentContext }) }];

const base = $('Add Tournament Context').first().json;
const pairs = $input.all().map((i) => i.json || {}).flatMap((j) => Array.isArray(j) ? j : (j.p1 && j.p2 ? [j] : []));
if (!pairs.length) return [{ json: base }];
const nameOf = (s) => { const i = s.lastIndexOf(' ('); return i >= 0 ? s.slice(0, i) : s; };
const teamOf = (s) => { const i = s.lastIndexOf('('); return i >= 0 ? s.slice(i + 1, s.lastIndexOf(')')) : s; };
const dayMatches = [];
for (const t of base.tournaments) {
  for (const m of t.matches) {
    const parts = String(m.score).split(' - ');
    dayMatches.push({ a: nameOf(m.home), b: nameOf(m.away), teamA: teamOf(m.home), teamB: teamOf(m.away), sa: Number(parts[0]), sb: Number(parts[1]), tournament: t.tournament, stage: m.stage });
  }
}
const key = (x, y) => [x, y].sort().join('|');
const headToHead = [];
const done = new Set();
for (const pair of pairs) {
  const A = pair.p1;
  const B = pair.p2;
  const k = key(A.name, B.name);
  if (done.has(k)) continue;
  const todays = dayMatches.filter((m) => key(m.a, m.b) === k);
  if (!todays.length) continue;
  done.add(k);
  let aw = 0; let bw = 0; let dr = 0; let ag = 0; let bg = 0;
  const list = [];
  let newBestWin = null;          // récord de la pareja (la mayor diferencia entre ambos)
  const newPersonalBestWins = []; // récord de un jugador contra ese rival, no de la pareja
  for (const m of todays) {
    const aIsHome = m.a === A.name;
    const goalsA = aIsHome ? m.sa : m.sb;
    const goalsB = aIsHome ? m.sb : m.sa;
    const teamA = aIsHome ? m.teamA : m.teamB;
    const teamB = aIsHome ? m.teamB : m.teamA;
    ag += goalsA; bg += goalsB;
    if (goalsA === goalsB) dr++; else if (goalsA > goalsB) aw++; else bw++;
    list.push({ tournament: m.tournament, stage: m.stage, result: A.name + ' (' + teamA + ') ' + goalsA + ' - ' + goalsB + ' (' + teamB + ') ' + B.name });
    if (goalsA === goalsB) continue;

    const aWon = goalsA > goalsB;
    const winner = aWon ? A : B;
    const loser = aWon ? B : A;
    const wTeam = aWon ? teamA : teamB;
    const lTeam = aWon ? teamB : teamA;
    const wGoals = Math.max(goalsA, goalsB);
    const lGoals = Math.min(goalsA, goalsB);
    const margin = wGoals - lGoals;

    // face-to-face se consulta después del día: bestWin ya incluye los partidos de hoy.
    const wb = winner.bestWin;
    const isPersonalBest = !!(wb && wb.teamThatWon && wb.teamThatLost
      && wb.teamThatWon.name === wTeam && wb.teamThatLost.name === lTeam
      && wb.scoreFromTeamThatWon === wGoals && wb.scoreFromTeamThatLost === lGoals);
    if (!isPersonalBest) continue;

    const lb = loser.bestWin;
    const loserBestMargin = lb && typeof lb.scoringDifference === 'number' ? lb.scoringDifference : 0;
    const rec = { player: winner.name, against: loser.name, margin, newRecordMatch: wTeam + ' ' + wGoals + ' - ' + lGoals + ' ' + lTeam, tournament: m.tournament, stage: m.stage };

    if (margin > loserBestMargin) {
      if (!newBestWin || margin > newBestWin.margin) {
        newBestWin = Object.assign({}, rec, { note: 'Biggest goal difference ever between these two players, in either direction.' });
      }
    } else {
      newPersonalBestWins.push(Object.assign({}, rec, {
        pairRecord: { player: loser.name, margin: loserBestMargin },
        note: 'Biggest win ever of ' + winner.name + ' against ' + loser.name + '. It is NOT the biggest difference between them: that record is ' + loserBestMargin + ' goals, held by ' + loser.name + '.',
      }));
    }
  }
  const after = { played: A.played, aWins: A.wins, draws: A.draws, bWins: B.wins, goalsA: A.goalsFor, goalsB: B.goalsFor };
  const before = { played: A.played - todays.length, aWins: A.wins - aw, draws: A.draws - dr, bWins: B.wins - bw, goalsA: A.goalsFor - ag, goalsB: B.goalsFor - bg };
  const sideWins = (w) => ({ [A.name]: w.aWins, [B.name]: w.bWins });
  const leader = (x) => x.aWins > x.bWins ? A.name : (x.bWins > x.aWins ? B.name : null);
  const lb = leader(before);
  const la = leader(after);
  headToHead.push({
    playerA: A.name,
    playerB: B.name,
    playedToday: list,
    allTimeAfterToday: { matches: after.played, winsByPlayer: sideWins(after), draws: after.draws, goalsByPlayer: { [A.name]: after.goalsA, [B.name]: after.goalsB } },
    allTimeBeforeToday: { matches: before.played, winsByPlayer: sideWins(before), draws: before.draws },
    leaderBefore: lb,
    leaderAfter: la,
    leadChanged: lb !== la,
    newBestWin,
    newPersonalBestWins,
  });
}
return [{ json: Object.assign({}, base, { headToHead }) }];

const base = $('Compute Head To Head').first().json;
const raw = $input.all().map((i) => i.json || {});
const list = raw.flatMap((j) => Array.isArray(j.data) ? j.data : []);
if (!list.length) return [{ json: base }];
const net = {};
for (const p of ((base.elo && base.elo.players) || [])) net[p.player] = p.netChange;
const rows = list.map((r) => {
  const name = r.player && r.player.name;
  const before = typeof net[name] === 'number' ? Math.round((r.rating - net[name]) * 10) / 10 : r.rating;
  return { player: name, rating: r.rating, peak: r.peak, matches: r.matches, provisional: !!r.provisional, atPeak: typeof r.peak === 'number' && r.rating >= r.peak, ratingBefore: before };
});
const posBefore = {};
rows.slice().sort((a, b) => b.ratingBefore - a.ratingBefore).forEach((r, i) => { posBefore[r.player] = i + 1; });
const ratings = rows.map((r, i) => Object.assign({ position: i + 1, positionBefore: posBefore[r.player] }, r));
return [{ json: Object.assign({}, base, { ratings }) }];

// ====== CONFIGURACIÓN ======
// Nombre EXACTO del nodo que llama a GET /api/recaps/context (sin transformar).
const CONTEXT_NODE = 'Fetch Tournament Context';
// ===========================

const d = $input.first().json;

// --- Respuesta cruda de /api/recaps/context (bracket, valid, playedAt, matchInsights) ---
const loadRawContext = () => {
  let items = null;
  try { items = $(CONTEXT_NODE).all().map((i) => i.json); } catch (e) { items = null; }
  if (!items && d.recapContextRaw) items = [d.recapContextRaw];
  if (!items) throw new Error('No encuentro el nodo "' + CONTEXT_NODE + '": corregí CONTEXT_NODE con el nombre del nodo que llama a /api/recaps/context.');
  return items.flatMap((j) => Array.isArray(j) ? j : Array.isArray(j.data) ? j.data : (j.tournamentId ? [j] : []));
};
const rawContext = loadRawContext();
if (!rawContext.length && (d.tournaments || []).length) throw new Error('La respuesta de /api/recaps/context vino vacía.');
const rawById = new Map(rawContext.map((c) => [String(c.tournamentId), c]));
const ctxById = new Map((d.tournamentContext || []).map((c) => [String(c.tournamentId), c]));

// --- Utilidades ---
const ROUNDS = { round_of_32: '16vos de final', round_of_16: '8vos de final', quarterfinal: '4tos de final', semifinal: 'semifinales', final: 'final' };
const roundLabel = (r) => ROUNDS[r] || r;
const dayStart = Date.parse(d.date + 'T03:00:00Z'); // día argentino (UTC-3, sin horario de verano)
const dayEnd = dayStart + 24 * 3600 * 1000;
const ms = (x) => (x ? Date.parse(x) : NaN);
const inDay = (x) => { const t = ms(x.playedAt); return t >= dayStart && t < dayEnd; };
const afterDay = (x) => ms(x.playedAt) >= dayEnd;
const nm = (o) => (o && o.name) || '?';
const fmt = (player, team) => player + ' (' + team + ')';
const splitName = (s) => { const i = s.lastIndexOf(' ('); return [s.slice(0, i), s.slice(i + 2, -1)]; };

// Partido del bracket crudo -> forma plana
const flat = (x) => ({
  leg: x.leg, playedAt: x.playedAt, valid: x.valid !== false,
  p1: nm(x.playerP1), t1: nm(x.teamP1), s1: x.scoreP1, p2: nm(x.playerP2), t2: nm(x.teamP2), s2: x.scoreP2,
  seed1: x.seedP1, seed2: x.seedP2,
  samePlayer: !!(x.playerP1 && x.playerP2 && String(x.playerP1.id) === String(x.playerP2.id)),
  winnerTeam: x.outcome && x.outcome.teamThatWon ? nm(x.outcome.teamThatWon) : null,
  winnerPlayer: x.outcome && x.outcome.playerThatWon ? nm(x.outcome.playerThatWon) : null,
  loserTeam: x.outcome && x.outcome.teamThatLost ? nm(x.outcome.teamThatLost) : null,
  loserPlayer: x.outcome && x.outcome.playerThatLost ? nm(x.outcome.playerThatLost) : null,
});
// Cómo se resolvió un partido con valid:false
const resolvedBy = (m) => m.samePlayer ? 'same_player_pick' : (m.leg === 3 ? 'golden_goal' : 'walkover');

// --- Cuotas previas de un partido (a partir de matchInsights) ---
// El BE ya trae el favorito (con las etiquetas del asistente) y los niveles de ventaja de ELO y de overall:
// acá solo se arma lo que lee el agente. No se pasan números de ELO de los jugadores y el overall de los
// equipos solo viaja cuando la diferencia es relevante.
const sideOf = (ins, side) => (side === 'p1' ? ins.p1 : ins.p2);
const oddsOf = (ins) => {
  const fav = ins.favorite; // undefined = BE sin los campos nuevos; null = duelo parejo
  let result;
  if (ins.winner === 'draw') result = 'draw';
  else if (fav === undefined) result = ins.winnerExpectedScore < 0.35 ? 'upset' : ins.winnerExpectedScore < 0.5 ? 'underdog_win' : 'favorite_win';
  else if (!fav) result = 'toss_up';
  else if (ins.winner === fav.side) result = 'favorite_win';
  else result = ins.winnerExpectedScore < 0.35 ? 'upset' : 'underdog_win';
  const o = {};
  if (fav) {
    const s = sideOf(ins, fav.side);
    o.favorite = { who: fmt(s.player.name, s.team.name), label: fav.label };
    o.favoriteExpected = Math.round((fav.side === 'p1' ? ins.expectedP1 : 1 - ins.expectedP1) * 1000) / 1000;
  }
  Object.assign(o, { result, winnerExpectedScore: ins.winnerExpectedScore, kind: ins.kind, ratingSwing: ins.ratingSwing });
  if (ins.ratingEdge) o.ratingEdge = { who: sideOf(ins, ins.ratingEdge.side).player.name, level: ins.ratingEdge.level };
  if (ins.overallGap) {
    const s = sideOf(ins, ins.overallGap.side);
    const overall = {}; overall[ins.p1.team.name] = ins.p1.teamOverall; overall[ins.p2.team.name] = ins.p2.teamOverall;
    o.overallEdge = { who: fmt(s.player.name, s.team.name), points: ins.overallGap.points, level: ins.overallGap.level, overall };
  }
  return o;
};
// Ronda a la que pasa el ganador de un cruce (null si el BE no la informa y no es la final)
const nextLabel = (b) => (b.round === 'final' ? 'campeón del torneo' : b.nextRound ? roundLabel(b.nextRound) : null);
// Cómo viene una serie de ida y vuelta tras la ida, según la diferencia de goles
const leadOf = (aggregate) => {
  if (aggregate.length < 2) return null;
  const sorted = aggregate.slice().sort((x, y) => y.score - x.score);
  const goals = sorted[0].score - sorted[1].score;
  const outlook = goals === 0 ? 'level' : goals === 1 ? 'open' : goals === 2 ? 'edge' : goals <= 4 ? 'steep' : 'very_steep';
  return { leader: goals ? sorted[0].team : null, trailing: goals ? sorted[1].team : null, goals, outlook };
};
// Puntaje para ordenar los destacados: sorpresa (65%) y margen (35%), con peso por etapa.
const STAGE_WEIGHT = { playoff: 1.25, playin: 1.1, regular: 1 };
const highlightScore = (stage, margin, winnerExpected) => {
  const surprise = typeof winnerExpected === 'number' ? 1 - winnerExpected : 0;
  const m = Math.min(margin || 0, 6) / 6;
  return Math.round(100 * (STAGE_WEIGHT[stage] || 1) * (0.65 * surprise + 0.35 * m));
};

const byTime = (list) => list.slice().sort((a, b) => a._t - b._t).map(({ _t, ...rest }) => rest);

const tournaments = [];
const tournamentContext = [];
const allMatches = [];

for (const t of d.tournaments || []) {
  const raw = rawById.get(String(t.tournamentId)) || {};
  const ctx = ctxById.get(String(t.tournamentId));
  const bracket = raw.bracket || [];
  const insights = raw.matchInsights || [];
  const insByTime = new Map(insights.map((i) => [Date.parse(i.playedAt), i]));
  const roundOf = (playoffId) => { const b = bracket.find((x) => x.playoffId === playoffId); return b ? roundLabel(b.round) : undefined; };

  // 1) Partidos jugados (válidos) en el orden en que se jugaron, con cuotas previas
  const sorted = t.matches.slice().sort((a, b) => String(a.time).localeCompare(String(b.time)));
  const matches = sorted.map((m, i) => {
    const o = { order: i + 1, stage: m.stage };
    if (m.playoffId != null) o.round = roundOf(m.playoffId);
    if (m.seeds) o.seeds = m.seeds;
    if (m.leg != null) o.leg = m.leg;
    o.home = m.home; o.away = m.away; o.score = m.score; o.margin = m.margin;
    const ins = insByTime.get(Date.parse(m.time));
    if (ins) o.odds = oddsOf(ins);
    if (m.stage === 'playoff' && m.playoffId != null && m.leg == null) {
      const tie = bracket.find((x) => x.playoffId === m.playoffId);
      const to = tie && nextLabel(tie);
      const won = tie && tie.matches.filter((x) => x.played).map(flat).find((x) => x.valid && ms(x.playedAt) === ms(m.time));
      if (to && won && won.winnerPlayer && won.winnerTeam) o.advancesTo = { winner: fmt(won.winnerPlayer, won.winnerTeam), to };
    }
    o.highlightScore = highlightScore(m.stage, m.margin, ins ? ins.winnerExpectedScore : null);
    allMatches.push({ tournament: t.tournament, order: o.order, text: m.home + ' ' + m.score + ' ' + m.away, score: o.highlightScore });
    return o;
  });
  const maxMargin = Math.max(0, ...matches.map((m) => m.margin || 0));

  // 2) Cruces del bracket que tuvieron algo ese día (partidos jugados, W.O., elecciones, desempates)
  const playoffSeries = [];
  const advancedWithoutPlaying = [];
  const teamNameById = new Map();
  for (const b of bracket) for (const x of b.matches) {
    if (x.teamP1 && x.teamP1.id != null) teamNameById.set(String(x.teamP1.id), nm(x.teamP1));
    if (x.teamP2 && x.teamP2.id != null) teamNameById.set(String(x.teamP2.id), nm(x.teamP2));
  }
  for (const b of bracket) {
    const legs = b.matches.filter((x) => x.played).map(flat);
    if (!legs.some(inDay)) continue;
    const round = roundLabel(b.round);
    const firstInDay = Math.min(...legs.filter(inDay).map((x) => ms(x.playedAt)));

    if (!b.series) {
      // Partido único: solo interesa si se resolvió sin jugarse
      for (const m of legs.filter((x) => inDay(x) && !x.valid)) {
        advancedWithoutPlaying.push({
          _t: firstInDay, round, seeds: m.seed1 + ' vs ' + m.seed2,
          advancing: fmt(m.winnerPlayer, m.winnerTeam), eliminated: fmt(m.loserPlayer, m.loserTeam),
          decidedBy: resolvedBy(m),
          ...(nextLabel(b) ? { advancesTo: { winner: fmt(m.winnerPlayer, m.winnerTeam), to: nextLabel(b) } } : {}),
        });
      }
      continue;
    }

    // Ida y vuelta, visto al cierre del día
    const asOf = legs.filter((x) => !afterDay(x)).sort((p, q) => p.leg - q.leg);
    const later = legs.filter(afterDay);
    const invalid = asOf.filter((x) => !x.valid).sort((p, q) => q.leg - p.leg)[0];
    const agg = {};
    for (const l of asOf) if (l.valid && l.leg <= 2) { agg[l.t1] = (agg[l.t1] || 0) + l.s1; agg[l.t2] = (agg[l.t2] || 0) + l.s2; }
    const aggregate = Object.keys(agg).map((team) => ({ team, score: agg[team] }));
    let status; let winner = null; let decidedBy = null;
    if (invalid) {
      status = 'decided'; winner = invalid.winnerTeam; decidedBy = resolvedBy(invalid);
    } else if (later.length) {
      const has = (n) => asOf.some((l) => l.leg === n);
      status = has(1) && has(2) ? 'level_after_two_legs_tiebreak_pending' : 'awaiting_leg2';
    } else {
      status = b.series.status;
      winner = b.series.winnerTeamId != null ? (teamNameById.get(String(b.series.winnerTeamId)) || null) : null;
    }
    const first = legs.find((x) => x.leg === 1) || legs[0];
    const lead = status === 'awaiting_leg2' ? leadOf(aggregate) : null;
    const to = winner ? nextLabel(b) : null;
    playoffSeries.push({
      _t: firstInDay, round, seeds: first.seed1 + ' vs ' + first.seed2, status, winner, decidedBy, aggregate,
      ...(lead ? { lead } : {}),
      ...(to ? { advancesTo: { winner, to } } : {}),
      legs: asOf.map((l) => l.valid
        ? { leg: l.leg, playedOnRecapDate: inDay(l), result: fmt(l.p1, l.t1) + ' ' + l.s1 + ' - ' + l.s2 + ' ' + fmt(l.p2, l.t2) }
        : { leg: l.leg, playedOnRecapDate: inDay(l), notPlayed: true, resolvedBy: resolvedBy(l) }),
    });
  }

  tournaments.push({
    tournament: t.tournament,
    matchCount: t.matchCount,
    matchesByStage: t.matchesByStage,
    matches,
    biggestMarginOrders: matches.filter((m) => m.margin === maxMargin && maxMargin > 0).map((m) => m.order),
    // Ordenados por cuándo pasó algo ese día (como los partidos)
    playoffSeries: byTime(playoffSeries),
    advancedWithoutPlaying: byTime(advancedWithoutPlaying),
  });

  // 3) Contexto de reglas y tablas (solo lo que se usa en "Qué significa")
  if (!ctx) continue;
  const regular = t.matches.filter((m) => m.stage === 'regular');
  const hasPlayoff = t.matches.some((m) => m.stage === 'playoff') || playoffSeries.length > 0 || advancedWithoutPlaying.length > 0;
  const rules = { description: ctx.rules && ctx.rules.description };
  if (hasPlayoff && ctx.rules) rules.knockout = ctx.rules.knockout;
  if (regular.length && ctx.rules) {
    rules.tableTiebreak = ctx.rules.tableTiebreak;
    if (ctx.rules.qualification) rules.qualification = { perGroup: ctx.rules.qualification.perGroup, bestThirds: ctx.rules.qualification.bestThirds };
  }
  if (regular.length && raw.playoffStartRound) rules.firstKnockoutRound = roundLabel(raw.playoffStartRound);
  const entry = { tournament: t.tournament, rules };
  if (regular.length && (ctx.standings || []).length) {
    const played = new Set();
    for (const m of regular) for (const s of [m.home, m.away]) { const [player, team] = splitName(s); played.add(player + '|' + team); }
    entry.standings = ctx.standings
      .filter((g) => g.teams.some((x) => played.has(x.player + '|' + x.team)))
      .map((g) => ({
        group: g.group, groupComplete: g.groupComplete,
        teams: g.teams.map((x) => ({
          position: x.position, previousPosition: x.previousPosition, team: x.team, player: x.player,
          points: x.points, goalDifference: x.goalsFor - x.goalsAgainst, played: x.played,
          remainingMatches: x.remainingMatches, maxPossiblePoints: x.maxPossiblePoints, positionLocked: x.positionLocked,
          playedThatDay: played.has(x.player + '|' + x.team),
        })),
      }));
  }
  if ((ctx.playin || []).length) entry.playin = ctx.playin;
  tournamentContext.push(entry);
}

// Los 3 partidos más destacados del día (todos los torneos)
const topHighlights = allMatches.slice().sort((a, b) => b.score - a.score).slice(0, 3)
  .map((m, i) => ({ rank: i + 1, tournament: m.tournament, order: m.order, match: m.text, highlightScore: m.score }));

// Récord del día de cada jugador sumando todos los torneos (V/E/D por resultado, penales = victoria)
const recordByPlayer = new Map();
for (const t of d.tournaments || []) for (const r of t.playerTable || []) {
  if (!recordByPlayer.has(r.player)) recordByPlayer.set(r.player, { player: r.player, wins: 0, draws: 0, losses: 0 });
  const acc = recordByPlayer.get(r.player);
  acc.wins += r.wins; acc.draws += r.draws; acc.losses += r.losses;
}
const dayRecord = [...recordByPlayer.values()].sort((a, b) => b.wins - a.wins || a.losses - b.losses || a.player.localeCompare(b.player));

// --- Rachas, forma, mano a mano y ranking (igual que antes) ---
const streakEvents = [];
const grouped = new Map();
for (const e of d.streakEvents || []) {
  if (e.event === 'ACTIVE_STREAK_EXTENDED' && e.takesOverFrom) {
    streakEvents.push({ event: e.event, player: e.player, length: e.length, startedThatDay: e.startedThatDay, streakTypes: [e.streakType], takesOverFrom: e.takesOverFrom });
  } else if (e.event === 'ACTIVE_STREAK_EXTENDED') {
    const k = e.player + '|' + e.length + '|' + e.startedThatDay;
    if (!grouped.has(k)) {
      const g = { event: e.event, player: e.player, length: e.length, startedThatDay: e.startedThatDay, streakTypes: [] };
      grouped.set(k, g); streakEvents.push(g);
    }
    grouped.get(k).streakTypes.push(e.streakType);
  } else {
    const { note, lastMatch, ...rest } = e;
    const lm = lastMatch;
    streakEvents.push(Object.assign({}, rest, lm ? { lastMatch: lm.tournament + ' (' + lm.stage + '): ' + e.player + ' (' + lm.team + ') ' + lm.score + ' ' + lm.opponent + ' (' + lm.opponentTeam + '), ' + lm.result } : {}));
  }
}
const playersForm = (d.playersForm || []).map((p) => ({ player: p.player, currentStreak: p.currentStreak, last10Outcomes: p.last10Outcomes }));
const headToHead = (d.headToHead || []).map((h) => {
  const o = {
    playerA: h.playerA, playerB: h.playerB,
    allTimeAfterToday: { winsByPlayer: h.allTimeAfterToday.winsByPlayer, draws: h.allTimeAfterToday.draws },
    allTimeBeforeToday: { winsByPlayer: h.allTimeBeforeToday.winsByPlayer, draws: h.allTimeBeforeToday.draws },
    leadChanged: h.leadChanged,
  };
  if (h.leadChanged) { o.leaderBefore = h.leaderBefore; o.leaderAfter = h.leaderAfter; }
  if (h.newBestWin) o.newBestWin = h.newBestWin;
  if (h.newPersonalBestWins && h.newPersonalBestWins.length) o.newPersonalBestWins = h.newPersonalBestWins;
  return o;
});
const ratings = (d.ratings || []).map((r) => ({ position: r.position, positionBefore: r.positionBefore, player: r.player, rating: r.rating, atPeak: r.atPeak, provisional: r.provisional }));

return [{ json: { date: d.date, matchCount: d.matchCount, tournamentCount: d.tournamentCount, elo: d.elo, topHighlights, tournaments, dayRecord, tournamentContext, streakEvents, playersForm, headToHead, ratings } }];
